def HOSTX(expr="happy", pose="point", say=None, appear=None, bx=1640, by=160):
    """Tí dẫn chuyện ở góc phải + (tuỳ chọn) bong bóng thoại."""
    els = [{"fn": "ti", "args": {"x": 1800, "y": 470, "s": 0.40, "pose": pose, "expr": expr, "flip": True}}]
    if say:
        els.append({"fn": "bubble", "args": {"x": bx, "y": by, "text": say, "tx": 1770, "ty": 230, "size": 28}})
    d = {"name": "host", "motion": "bob", "elements": els}
    if appear is not None:
        d["appear"] = appear
    return d


def L(name, elements, motion="none", appear=None, **kw):
    d = {"name": name, "motion": motion, "elements": elements}
    if appear is not None:
        d["appear"] = appear
    d.update(kw)
    return d


def E(fn, **args):
    return {"fn": fn, "args": args}


def N(text, say=None):
    return {"text": text, **({"say": say} if say else {})}


